// Replace every example.com address before publishing the workflow.
const shared = {
  sender: 'Coffee Newsletter <user@example.com>',
  feed_url: 'https://news.ycombinator.com/rss',
  max_articles: 5,
};

const audiences = {
  paris: {
    timezone: 'Europe/Paris',
    locale: 'fr-FR',
    recipient: 'user@example.com',
    greeting: 'Bonjour Paris',
    subject_prefix: 'Votre pause café',
    intro: 'Voici les articles à découvrir avec votre café ce matin.',
    footer: 'Envoyé à 09:00 heure locale grâce à rrule.net et n8n.',
  },
  new_york: {
    timezone: 'America/New_York',
    locale: 'en-US',
    recipient: 'user@example.com',
    greeting: 'Good morning New York',
    subject_prefix: 'Your morning coffee',
    intro: 'Here are a few stories to explore with your coffee this morning.',
    footer: 'Delivered at 09:00 local time with rrule.net and n8n.',
  },
  tokyo: {
    timezone: 'Asia/Tokyo',
    locale: 'ja-JP',
    recipient: 'user@example.com',
    greeting: 'おはようございます、東京',
    subject_prefix: '朝のコーヒーニュース',
    intro: '今朝のコーヒーと一緒に読みたい記事をお届けします。',
    footer: 'rrule.net と n8n により現地時間09:00に配信されました。',
  },
  perth: {
    timezone: 'Australia/Perth',
    locale: 'en-AU',
    recipient: 'user@example.com',
    greeting: 'Good morning Perth',
    subject_prefix: 'Your morning coffee',
    intro: 'Here are a few stories to explore with your coffee this morning.',
    footer: 'Delivered at 09:00 local time with rrule.net and n8n.',
  },
};

return $input.all().map((item, itemIndex) => {
  const targetId = String(item.json.target_id ?? '');
  const audience = audiences[targetId];

  if (!audience) {
    throw new Error(`No audience configuration exists for target_id ${targetId}. Update the audiences map before publishing.`);
  }

  if (item.json.target_timezone && item.json.target_timezone !== audience.timezone) {
    throw new Error(`Unexpected timezone ${item.json.target_timezone} for target_id ${targetId}. Expected ${audience.timezone}.`);
  }

  return {
    json: {
      ...item.json,
      ...shared,
      ...audience,
    },
    pairedItem: { item: itemIndex },
  };
});

const config = $('Configure regional audiences').first().json;

const escapeHtml = (value) => String(value ?? '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('\"', '&quot;')
  .replaceAll("'", '&#039;');

const safeUrl = (value) => {
  const url = String(value ?? '').trim();
  return /^https?:\/\/[^\s<>"']+$/i.test(url) ? url : '#';
};

const articleLimit = Math.max(1, Math.min(10, Number(config.max_articles) || 5));
const articles = $input.all()
  .map((item) => item.json)
  .filter((article) => typeof article.title === 'string' && typeof article.link === 'string')
  .slice(0, articleLimit);

if (articles.length === 0) {
  throw new Error('The RSS feed returned no usable articles. Check feed_url before publishing.');
}

const scheduledDate = new Date(String(config.scheduled_for || new Date().toISOString()));
const displayDate = new Intl.DateTimeFormat(String(config.locale), {
  dateStyle: 'full',
  timeZone: String(config.timezone),
}).format(scheduledDate);

const articleHtml = articles.map((article) => {
  const title = escapeHtml(article.title);
  const link = escapeHtml(safeUrl(article.link));
  const rawSnippet = String(article.contentSnippet ?? '').trim();
  const snippet = /^Article URL:/i.test(rawSnippet) ? '' : escapeHtml(rawSnippet.slice(0, 240));
  const description = snippet ? `<p style=\"margin:8px 0 0;color:#5f5149;font-size:14px;font-weight:400;line-height:1.5;\">${snippet}</p>` : '';
  return `<li style=\"margin:0 0 22px;padding-left:4px;color:#6f3f21;font-size:17px;font-weight:700;line-height:1.4;\"><a href=\"${link}\" style=\"color:#6f3f21;font-size:17px;font-weight:700;line-height:1.4;text-decoration:none;\">${title}</a>${description}</li>`;
}).join('');

const html = `<!doctype html>
<html lang=\"${escapeHtml(String(config.locale).split('-')[0] || 'en')}\">
  <head>
    <meta charset=\"utf-8\">
    <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">
  </head>
  <body style=\"margin:0;background:#f7f1eb;font-family:Arial,sans-serif;color:#2d241f;\">
    <div style=\"display:none;max-height:0;overflow:hidden;opacity:0;color:transparent;\">${escapeHtml(config.intro)}</div>
    <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"background:#f7f1eb;padding:24px 12px;\">
      <tr><td align=\"center\">
        <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"max-width:640px;background:#ffffff;border-radius:14px;overflow:hidden;\">
          <tr><td style=\"background:#5b3825;padding:28px 32px;color:#ffffff;\">
            <div style=\"font-size:13px;letter-spacing:.08em;text-transform:uppercase;opacity:.8;\">${escapeHtml(displayDate)}</div>
            <h1 style=\"margin:10px 0 0;font-size:28px;\">☕ ${escapeHtml(config.greeting)}</h1>
          </td></tr>
          <tr><td style=\"padding:30px 32px;\">
            <p style=\"margin:0 0 24px;font-size:16px;line-height:1.6;\">${escapeHtml(config.intro)}</p>
            <ol style=\"margin:0;padding-left:24px;\">${articleHtml}</ol>
          </td></tr>
          <tr><td style=\"padding:20px 32px;background:#efe3d7;color:#6b5a50;font-size:12px;line-height:1.5;\">
            ${escapeHtml(config.footer)}<br>Target: ${escapeHtml(config.target_id)} · ${escapeHtml(config.target_timezone)}
          </td></tr>
        </table>
      </td></tr>
    </table>
  </body>
</html>`;

return [{
  json: {
    execution_id: config.execution_id,
    scheduled_for: config.scheduled_for,
    target_id: config.target_id,
    target_timezone: config.target_timezone,
    recipient: config.recipient,
    sender: config.sender,
    subject: `${config.subject_prefix} — ${displayDate}`,
    html,
    article_count: articles.length,
  },
}];
